} from "./extraction-budget";
import {
  ESTIMATE_TIMEOUT_MS,
  FlowRhythmEstimator,
  rhythmRequest,
} from "./flow-rhythm-estimator";
import type { ExtractionRequest, ExtractionResult } from "./extraction";

let now = 100_000;
const restores: Array<() => void> = [];
const estimators: FlowRhythmEstimator[] = [];
beforeEach(() => {
  now = 100_000;
  __resetExtractionBudgetForTests();
  const clock = spyOn(Date, "now").mockImplementation(() => now);
  restores.push(() => clock.mockRestore());
});
afterEach(() => {
  for (const estimator of estimators.splice(0)) estimator.invalidate();
  for (const restore of restores.splice(0).reverse()) restore();
});
const result: ExtractionResult = {
  ok: true,
  answers: {
    focus_remaining: {
      type: "estimate",
      value: 100,
      p10: 80,
      median: 100,
      p90: 120,
    },
    pause_length: { type: "estimate", value: 10, p10: 5, median: 10, p90: 20 },
  },
};
const input = (
  ask?: (request: ExtractionRequest) => Promise<ExtractionResult>,
) => ({
  now,
  lastKeyAt: now - 4000,
  runStartedAt: now - 94_000,
  runSeconds: 90,
  deleteRatio: 0.1,
  exitPauseMs: 25_000,
  samples: [{ at: now - 4000, inserted: 5, deleted: 0 }],
  profile: {
    ...emptyProfile(),
    runs: Array(8).fill(240_000),
    pauses: Array(8).fill(10_000),
  },
  ask,
});
const estimator = () => {
  const e = new FlowRhythmEstimator();
  e.log = Array.from({ length: 8 }, (_, i) => ({
    id: `history:${i}`,
    source: "baseline" as const,
    at: i + 1,
    lastKeyAt: 0,
    runStartedAt: 0,
    runSeconds: 0,
    pauseSeconds: 0,
    estimate: { focus: null, pause: null },
    actualFocus: 150,
    actualPause: 6,
  }));
  estimators.push(e);
  return e;
};
const newPredictions = (e: FlowRhythmEstimator) =>
  e.log.filter((p) => !p.id.startsWith("history:"));
async function flush() {
  for (let i = 0; i < 20; i++) await Promise.resolve();
}
function deferred<T>() {
  let resolve!: (result: T) => void;
  const promise = new Promise<T>((done) => {
    resolve = done;
  });
  return { promise, resolve };
}

test("focus includes zero on a linear grid; pause is logarithmic; state is rhythm only", () => {
