  const log = calibratedLog(100);
  expect(calibration(log, "clairic", "focus").count).toBe(50);
  expect(trustClairic(log)).toBe(true);
  let bounded: RhythmPrediction[] = [];
  for (let i = 0; i < 300; i++)
