function seedFocusOutcomes() {
  metadata.set(
    PREDICTION_LOG_KEY,
    Array.from({ length: 8 }, (_, i) => ({
      id: `history:${i}`,
      source: "baseline",
      at: i + 1,
      runStartedAt: 0,
      lastKeyAt: 0,
      runSeconds: 0,
      pauseSeconds: 0,
      estimate: { focus: null, pause: null },
      actualFocus: 150,
      actualPause: 6,
    })),
  );
}

test("empirical rhythm keeps flow through a thinking pause and logs actual stopped focus", async () => {
  resetRequests();
  const time = clock();
  seedFocusOutcomes();
  metadata.set("flow-profile", {
    version: 1,
    runs: Array(8).fill(240_000),
    pauses: Array(8).fill(10_000),
    flowEntries: [],
    hours: Array(24).fill(0),
    kinds: {},
    overrides: 0,
    updatedAt: 0,
  });
  const current = start("rhythm-folio", false);
  await enterFlow(current, time);
  time.advance(4000);
  current.tick();
  expect(flowSnapshot().mode).toBe("flow");
  time.advance(22_000);
  current.tick();
  expect(flowSnapshot().mode).toBe("flow");
  expect(extractionRequests).toHaveLength(0);
  current.stop();
  await flush();
  const log = (
    metadata.get(PREDICTION_LOG_KEY) as Array<{
      id: string;
      source: string;
      actualFocus: number;
    }>
  ).filter((p) => !p.id.startsWith("history:"));
  expect(log[0].source).toBe("baseline");
  expect(log[0].actualFocus).toBe(0);
});

test("reference focus outcomes span short pauses independently of the UI gate", async () => {
  resetRequests();
  const time = clock();
  const current = start("rhythm-outcomes", false);
  await enterFlow(current, time);
  time.advance(4000);
  current.tick();
  time.advance(1000);
  current.edit(" resumed");
  for (let i = 0; i < 10; i++) {
    time.advance(1000);
    current.edit(" word");
  }
  time.advance(25_000);
  current.tick();
  current.stop();
  await flush();
  const log = metadata.get(PREDICTION_LOG_KEY) as Array<{
    actualFocus?: number;
    actualPause?: number;
  }>;
  expect(log[0]).toMatchObject({ actualFocus: 11, actualPause: 1 });
});

