    const url = new URL(process.env.CONVEX_CLOUD_URL ?? "");
    if (
      !["http:", "https:"].includes(url.protocol) ||
      !["localhost", "127.0.0.1", "[::1]"].includes(url.hostname)
    )
      return null;
  } catch {
    return null;
  }
  const token = process.env.CLOUDFLARE_AI_API_TOKEN?.trim();
  const account = process.env.CLOUDFLARE_ACCOUNT_ID?.trim();
  return token && account ? { token, account } : null;
}

function transport(): ExtractionTransport {
  if (notOrganicEnabled()) return "notorganic";
  if (directCredentials()) return "direct";
  return "none";
}

export const isAvailable = action({
  args: {},
  returns: v.object({
    available: v.boolean(),
    transport: v.union(
      v.literal("notorganic"),
      v.literal("direct"),
      v.literal("none"),
    ),
  }),
  handler: async (): Promise<{
    available: boolean;
    transport: ExtractionTransport;
  }> => {
    const via = transport();
    return { available: via !== "none", transport: via };
  },
});

interface ExtractionBody {
  model: string;
  answers: Record<string, unknown>;
  truncated: boolean;
  usage?: { input_tokens: number; output_tokens: number; passes?: number };
}

type Outcome = { ok: true; body: unknown } | { ok: false; error: string };

/** Never surface upstream bodies: they can echo the request, i.e. the draft. */
function statusError(status: number): string {
  if (status === 429) return "rate limited";
  if (status === 529 || status === 503) return "overloaded";
  if (status === 401 || status === 403) return "unauthorized";
  if (status === 402) return "no credit";
  if (status === 404) return "unsupported";
  if (status === 400 || status === 422) return "malformed";
  return "provider";
}

async function extractNotOrganic(
  ctx: ActionCtx,
  body: Record<string, unknown>,
): Promise<Outcome> {
  const identity = await ctx.auth.getUserIdentity();
  if (!identity) return { ok: false, error: "signed out" };
  const link = await ctx.runQuery(linkedDidReference, {
    productSubject: identity.subject || identity.tokenIdentifier,
  });
  if (!link) return { ok: false, error: "account not linked" };
  try {
    const token = await issueNotOrganicAccessToken({
      did: link.did,
      feature: EXTRACTION_FEATURE,
      capabilities: [EXTRACTION_CAPABILITY],
      sessionVersion: link.sessionVersion,
    });
    const result = await providerJsonRequest<ExtractionBody>(
      EXTRACTION_PATH,
      token,
      {
        method: "POST",
        signal: AbortSignal.timeout(40_000),
        body: JSON.stringify(body),
        // Fresh per attempt, as in systemOne: an edited draft is a new read.
        headers: { "idempotency-key": crypto.randomUUID() },
      },
      { issuer: notOrganicIssuer(), feature: EXTRACTION_FEATURE },
    );
    return { ok: true, body: result };
  } catch (error) {
    const message = error instanceof Error ? error.message : "";
    const status =
      /^Not Organic (?:API|token exchange) failed \((\d{3})\)/.exec(
        message,
      )?.[1];
    return {
      ok: false,
      error: status ? statusError(Number(status)) : extractionError(error),
    };
  }
}

/** Local-development path. Never reached when Not Organic is enabled. */
async function extractDirect(
  credentials: { token: string; account: string },
  body: Record<string, unknown>,
): Promise<Outcome> {
  let res: Response;
  try {
    res = await fetch(
      `https://api.cloudflare.com/client/v4/accounts/${encodeURIComponent(credentials.account)}/ai/run/${CLAIRIC}`,
      {
        method: "POST",
        signal: AbortSignal.timeout(30_000),
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${credentials.token}`,
        },
        body: JSON.stringify({ model: "clairic", ...body }),
      },
    );
  } catch {
    return { ok: false, error: "network" };
  }
  if (!res.ok) return { ok: false, error: statusError(res.status) };
  try {
    const json: unknown = await res.json();
    if (!json || typeof json !== "object" || Array.isArray(json))
      return { ok: false, error: "provider" };
    const envelope = json as Record<string, unknown>;
    const payload = envelope.result ?? envelope;
    if (!payload || typeof payload !== "object" || Array.isArray(payload))
      return { ok: false, error: "provider" };
    const result = payload as Record<string, unknown>;
    if (
      typeof result.model !== "string" ||
      !/^(?:clairic|@cf\/cloudflare\/clairic)(?:[-@:.][\w.-]+)?$/.test(
        result.model,
      )
    )
      return { ok: false, error: "provider" };
    return {
      ok: true,
      body: {
        ...result,
        model: `extraction-clairic/${result.model.replace(/^@cf\/cloudflare\//, "")}`,
      },
    };
  } catch {
    return { ok: false, error: "provider" };
  }
}

function validatedBody(
  raw: unknown,
  request: ExtractionRequest,
): ExtractionBody | null {
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return null;
  const body = raw as Record<string, unknown>;
  if (
    typeof body.model !== "string" ||
    !/^extraction-clairic\/clairic(?:[-@:.][\w.-]+)?$/.test(body.model) ||
    typeof body.truncated !== "boolean"
  )
    return null;
  try {
    const answers = validateExtractionAnswers(request, body.answers);
    const usage = body.usage as Record<string, unknown> | undefined;
    const count = (n: unknown): n is number =>
      typeof n === "number" && Number.isSafeInteger(n) && n >= 0;
    if (
      usage != null &&
      (typeof usage !== "object" ||
        Array.isArray(usage) ||
        !count(usage.input_tokens) ||
        !count(usage.output_tokens) ||
        (usage.passes !== undefined && !count(usage.passes)))
    )
      return null;
    return {
      model: body.model,
      answers,
      truncated: body.truncated,
      ...(usage
        ? {
            usage: {
              input_tokens: usage.input_tokens as number,
              output_tokens: usage.output_tokens as number,
              ...(usage.passes !== undefined
                ? { passes: usage.passes as number }
                : {}),
            },
          }
        : {}),
    };
  } catch {
    return null;
  }
}

export const extract = action({
  args: {
    state: v.optional(v.string()),
    fields: v.record(v.string(), fieldValidator),
    reference_date: v.optional(v.string()),
    options: v.optional(
      v.object({
        include_quantiles: v.optional(v.boolean()),
        return_state_text: v.optional(v.boolean()),
      }),
    ),
  },
  returns: v.object({
    ok: v.boolean(),
    model: v.optional(v.string()),
    answers: v.optional(v.record(v.string(), v.any())),
    truncated: v.optional(v.boolean()),
    usage: v.optional(
      v.object({
        input_tokens: v.number(),
        output_tokens: v.number(),
        passes: v.optional(v.number()),
      }),
    ),
    transport: v.optional(
      v.union(v.literal("notorganic"), v.literal("direct"), v.literal("none")),
    ),
    error: v.optional(v.string()),
  }),
  handler: async (
    ctx,
    args,
  ): Promise<{
    ok: boolean;
    model?: string;
    answers?: Record<string, unknown>;
    truncated?: boolean;
    usage?: { input_tokens: number; output_tokens: number; passes?: number };
    transport?: ExtractionTransport;
    error?: string;
  }> => {
    const via = transport();
    if (via === "none") return { ok: false, error: "unconfigured" };
    const names = Object.keys(args.fields);
    if (names.length === 0) return { ok: false, error: "no fields" };
    if (names.length > MAX_FIELDS)
      return { ok: false, error: `too many fields (${names.length})` };
    if (!args.state?.trim()) return { ok: false, error: "empty state" };
    if (args.state.length > MAX_STATE_CHARS)
      return { ok: false, error: "state too large" };

    try {
      const identity = await ctx.auth.getUserIdentity();
      if (!identity) return { ok: false, error: "signed out" };
      const isPro = await userIsPro(
        ctx,
        identity.subject || identity.tokenIdentifier,
      );
      await consumeRateLimit(ctx, {
        action: "extraction:extract",
        identifier: identity.tokenIdentifier,
        ...(isPro ? RATE_LIMITS.extraction : RATE_LIMITS.extractionFree),
      });

      const body = {
        state: args.state,
        fields: args.fields,
        ...(args.reference_date ? { reference_date: args.reference_date } : {}),
        ...(args.options ? { options: args.options } : {}),
      };
      const result =
        via === "notorganic"
          ? await extractNotOrganic(ctx, body)
          : await extractDirect(directCredentials()!, body);
      if (!result.ok) return { ok: false, transport: via, error: result.error };
      const response = validatedBody(result.body, args);
      if (!response) return { ok: false, transport: via, error: "provider" };
      const usage = response.usage;
      return {
        ok: true,
        transport: via,
        model: response.model,
        answers: response.answers,
        truncated: response.truncated,
        ...(usage &&
        typeof usage.input_tokens === "number" &&
        typeof usage.output_tokens === "number"
          ? {
              usage: {
                input_tokens: usage.input_tokens,
                output_tokens: usage.output_tokens,
                ...(typeof usage.passes === "number"
                  ? { passes: usage.passes }
                  : {}),
              },
            }
          : {}),
      };
    } catch (error) {
      return { ok: false, transport: via, error: extractionError(error) };
    }
  },
});
# Convex guidelines

These guidelines target Convex `^1.41.0`.

## Function guidelines

### Http endpoint syntax

- HTTP endpoints are defined in `convex/http.ts` and require an `httpAction` decorator. For example:

```typescript
import { httpRouter } from "convex/server";
import { httpAction } from "./_generated/server";
const http = httpRouter();
http.route({
  path: "/echo",
  method: "POST",
  handler: httpAction(async (ctx, req) => {
    const body = await req.bytes();
    return new Response(body, { status: 200 });
  }),
});
```

- Treat the result of `await req.json()` as `unknown` - narrow each field (e.g. `typeof` checks) before use, and return a 400 response for bodies that fail validation.
- HTTP endpoints are always registered at the exact path you specify in the `path` field. For example, if you specify `/api/someRoute`, the endpoint will be registered at `/api/someRoute`.

### Validators

- Below is an example of an array validator:

```typescript
import { mutation } from "./_generated/server";
import { v } from "convex/values";

export default mutation({
  args: {
    simpleArray: v.array(v.union(v.string(), v.number())),
  },
  handler: async (ctx, args) => {
    //...
  },
});
```

- `v.object(...)` validators compose: `.pick("a", "b")`, `.omit("c")`, `.partial()`, and `.extend({ d: v.string() })` derive new object validators from an existing one - define a shape once and derive variants instead of duplicating fields. Use an object validator's `.fields` to supply function `args`.
- Below is an example of a schema with validators that codify a discriminated union type:

```typescript
import { defineSchema, defineTable } from "convex/server";
import { v } from "convex/values";

export default defineSchema({
  results: defineTable(
    v.union(
      v.object({
        kind: v.literal("error"),
        errorMessage: v.string(),
      }),
      v.object({
        kind: v.literal("success"),
        value: v.number(),
      }),
    ),
  ),
});
```

- Here are the valid Convex types along with their respective validators:
  | Convex Type | TS/JS type | Example Usage | Validator for argument validation and schemas | Notes |
  | ----------- | ----------- | -------------------- | --------------------------------------------- | ------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ |
  | Id | string | `doc._id` | `v.id(tableName)` | |
  | Null | null | `null` | `v.null()` | JavaScript's `undefined` is not a valid Convex value. Functions the return `undefined` or do not return will return `null` when called from a client. Use `null` instead. |
  | Int64 | bigint | `3n` | `v.int64()` | Int64s only support BigInts between -2^63 and 2^63-1. Convex supports `bigint`s in most modern browsers. |
  | Float64 | number | `3.1` | `v.number()` | Convex supports all IEEE-754 double-precision floating point numbers (such as NaNs). Inf and NaN are JSON serialized as strings. |
  | Boolean | boolean | `true` | `v.boolean()` |
  | String | string | `"abc"` | `v.string()` | Strings are stored as UTF-8 and must be valid Unicode sequences. Strings must be smaller than the 1MB total size limit when encoded as UTF-8. |
  | Bytes | ArrayBuffer | `new ArrayBuffer(8)` | `v.bytes()` | Convex supports first class bytestrings, passed in as `ArrayBuffer`s. Bytestrings must be smaller than the 1MB total size limit for Convex types. |
  | Array | Array | `[1, 3.2, "abc"]` | `v.array(values)` | Arrays can have at most 8192 values. |
  | Object | Object | `{a: "abc"}` | `v.object({property: value})` | Convex only supports "plain old JavaScript objects" (objects that do not have a custom prototype). Objects can have at most 1024 entries. Field names must be nonempty and not start with "$" or "\_". |

| Record | Record | `{"a": "1", "b": "2"}` | `v.record(keys, values)` | Records are objects at runtime, but can have dynamic keys. Keys must be only ASCII characters, nonempty, and not start with "$" or "\_". |

### Function registration

- Use `internalQuery`, `internalMutation`, and `internalAction` to register internal functions. These functions are private and aren't part of an app's API. They can only be called by other Convex functions. These functions are always imported from `./_generated/server`.
- Use `query`, `mutation`, and `action` to register public functions. These functions are part of the public API and are exposed to the public Internet. Do NOT use `query`, `mutation`, or `action` to register sensitive internal functions that should be kept private. A function invoked only by your own code - e.g. the mutation an HTTP action calls to commit its effects - is internal, not public.
- You CANNOT register a function through the `api` or `internal` objects.
- ALWAYS include argument validators for all Convex functions. This includes all of `query`, `internalQuery`, `mutation`, `internalMutation`, `action`, and `internalAction`.

### Function calling

- Use `ctx.runQuery` to call a query from a query, mutation, or action.
- Use `ctx.runMutation` to call a mutation from a mutation or action.
- Use `ctx.runAction` to call an action from an action.
- ONLY call an action from another action if you need to cross runtimes (e.g. from V8 to Node). Otherwise, pull out the shared code into a helper async function and call that directly instead.
- Try to use as few calls from actions to queries and mutations as possible. Queries and mutations are transactions, so splitting logic up into multiple calls introduces the risk of race conditions.
- All of these calls take in a `FunctionReference`. Do NOT try to pass the callee function directly into one of these calls.
- Nested `ctx.runQuery` and `ctx.runMutation` calls from a mutation execute as subtransactions. If a nested call throws, its writes roll back independently, so the caller can catch the error and continue with its own writes intact.
- In Convex 1.41+, `ctx.runQuery` and `ctx.runMutation` accept an optional third argument with `transactionLimits`. These limits cap how much the nested call may additionally consume on top of what the caller has already used - they can only tighten the global transaction limits, never raise them. If the nested call exceeds its cap and rolls back, the caller keeps its own remaining budget, which is useful for preserving caller headroom. For example:

```ts
try {
  await ctx.runMutation(internal.example.writeBatch, args, {
    transactionLimits: { documentsWritten: 100, bytesWritten: 1024 * 1024 },
  });
} catch (e) {
  // The nested mutation's writes rolled back; this mutation can still write.
}
```

The supported `transactionLimits` fields are `bytesRead`, `bytesWritten`, `databaseQueries`, `documentsRead`, `documentsWritten`, `functionsScheduled`, and `scheduledFunctionArgsBytes`.

- When using `ctx.runQuery`, `ctx.runMutation`, or `ctx.runAction` to call a function in the same file, specify a type annotation on the return value to work around TypeScript circularity limitations. For example,

```
export const f = query({
  args: { name: v.string() },
  handler: async (ctx, args) => {
    return "Hello " + args.name;
  },
});

export const g = query({
  args: {},
  handler: async (ctx, args) => {
    const result: string = await ctx.runQuery(api.example.f, { name: "Bob" });
    return null;
  },
});
```

### Function references

- Use the `api` object defined by the framework in `convex/_generated/api.ts` to call public functions registered with `query`, `mutation`, or `action`.
- Use the `internal` object defined by the framework in `convex/_generated/api.ts` to call internal (or private) functions registered with `internalQuery`, `internalMutation`, or `internalAction`.
- Convex uses file-based routing, so a public function defined in `convex/example.ts` named `f` has a function reference of `api.example.f`.
- A private function defined in `convex/example.ts` named `g` has a function reference of `internal.example.g`.
- Functions can also registered within directories nested within the `convex/` folder. For example, a public function `h` defined in `convex/messages/access.ts` has a function reference of `api.messages.access.h`.

### Pagination

- Define pagination using the following syntax:

```ts
import { v } from "convex/values";
import { query, mutation } from "./_generated/server";
import { paginationOptsValidator } from "convex/server";
export const listWithExtraArg = query({
  args: { paginationOpts: paginationOptsValidator, author: v.string() },
  handler: async (ctx, args) => {
    return await ctx.db
      .query("messages")
      .withIndex("by_author", (q) => q.eq("author", args.author))
      .order("desc")
      .paginate(args.paginationOpts);
  },
});
```

Note: `paginationOpts` is an object with the following properties:

- `numItems`: the initial page-size target — not a guaranteed maximum under reactive pagination (the validator is `v.number()`)
- `cursor`: the cursor to use to fetch the next page of documents; required (the validator is `v.union(v.string(), v.null())`)
- `endCursor` (optional): bounds the page to end at a known cursor
- `maximumRowsRead` (optional): limits how many rows the query may scan before returning a partial page
- `maximumBytesRead` (optional): limits how many bytes the query may read before returning a partial page
- `id` (optional): client-managed pagination metadata accepted by `paginationOptsValidator`

Always validate pagination arguments with `paginationOptsValidator` and pass `args.paginationOpts` unchanged to `.paginate()` — do not reconstruct it field by field, or the optional fields lose their native behavior.

A query that ends in `.paginate()` returns an object that has the following properties:

- `page`: an array of the documents fetched for this page
- `isDone`: a boolean representing whether this is the last page of documents
- `continueCursor`: a string cursor to fetch the next page of documents
- `splitCursor` (optional, string or null) and `pageStatus` (optional, `"SplitRecommended"`, `"SplitRequired"`, or null): present when the page was cut short and should be split

For the return validator of a paginated query, use `paginationResultValidator(itemValidator)` from `convex/server` rather than reproducing this shape by hand.

## Schema guidelines

- Always define your schema in `convex/schema.ts`.
- Always import the schema definition functions from `convex/server`.
- System fields are automatically added to all documents and are prefixed with an underscore. The two system fields that are automatically added to all documents are `_creationTime` which has the validator `v.number()` and `_id` which has the validator `v.id(tableName)`.
- Always include all index fields in the index name. For example, if an index is defined as `["field1", "field2"]`, the index name should be "by_field1_and_field2".
- Index fields must be queried in the same order they are defined. If you want to be able to query by "field1" then "field2" and by "field2" then "field1", you must create separate indexes.
- Do not store unbounded lists as an array field inside a document (e.g. `v.array(v.object({...}))`). As the array grows it will hit the 1MB document size limit, and every update rewrites the entire document. Instead, create a separate table for the child items with a foreign key back to the parent.
- Separate high-churn operational data (e.g. heartbeats, online status, typing indicators) from stable profile data. Storing frequently updated fields on a shared document forces every write to contend with reads of the entire document. Instead, create a dedicated table for the high-churn data with a foreign key back to the parent record.

- Adding an index to a large existing table blocks the deploy until backfill completes. Declare it staged - `.index("by_field", { fields: ["field"], staged: true })` - to backfill asynchronously without blocking; a staged index cannot be queried until a later deploy removes the flag.

## Authentication guidelines

- Convex supports JWT-based authentication through `convex/auth.config.ts`. ALWAYS create this file when using authentication. Without it, `ctx.auth.getUserIdentity()` will always return `null`.
- Example `convex/auth.config.ts`:

```typescript
export default {
  providers: [
    {
      domain: "https://your-auth-provider.com",
      applicationID: "convex",
    },
  ],
};
```

The `domain` must be the issuer URL of the JWT provider. Convex fetches `{domain}/.well-known/openid-configuration` to discover the JWKS endpoint. The `applicationID` is checked against the JWT `aud` (audience) claim.

- Use `ctx.auth.getUserIdentity()` to get the authenticated user's identity in any query, mutation, or action. This returns `null` if the user is not authenticated, or a `UserIdentity` object with fields like `subject`, `issuer`, `name`, `email`, etc. The `subject` field is the unique user identifier.
- In Convex `UserIdentity`, `tokenIdentifier` is guaranteed and is the canonical stable identifier for the authenticated identity. For any auth-linked database lookup or ownership check, prefer `identity.tokenIdentifier` over `identity.subject`. Do NOT use `identity.subject` alone as a global identity key.
- NEVER accept a `userId` or any user identifier as a function argument for authorization purposes. Always derive the user identity server-side via `ctx.auth.getUserIdentity()`.
- When using an external auth provider with Convex on the client, use `ConvexProviderWithAuth` instead of `ConvexProvider`:

```tsx
import { ConvexProviderWithAuth, ConvexReactClient } from "convex/react";

const convex = new ConvexReactClient(process.env.NEXT_PUBLIC_CONVEX_URL!);

function App({ children }: { children: React.ReactNode }) {
  return (
    <ConvexProviderWithAuth client={convex} useAuth={useYourAuthHook}>
      {children}
    </ConvexProviderWithAuth>
  );
}
```

The `useAuth` prop must return `{ isLoading, isAuthenticated, fetchAccessToken }`. Do NOT use plain `ConvexProvider` when authentication is needed — it will not send tokens with requests.

## Typescript guidelines

- You can use the helper typescript type `Id` imported from './\_generated/dataModel' to get the type of the id for a given table. For example if there is a table called 'users' you can use `Id<'users'>` to get the type of the id for that table.
- Use `Doc<"tableName">` from `./_generated/dataModel` to get the full document type for a table.
- Use `QueryCtx`, `MutationCtx`, `ActionCtx` from `./_generated/server` for typing function contexts. NEVER use `any` for ctx parameters — always use the proper context type.
- If you need to define a `Record` make sure that you correctly provide the type of the key and value in the type. For example a validator `v.record(v.id('users'), v.string())` would have the type `Record<Id<'users'>, string>`. Below is an example of using `Record` with an `Id` type in a query:

```ts
import { query } from "./_generated/server";
import { Doc, Id } from "./_generated/dataModel";

export const exampleQuery = query({
  args: { userIds: v.array(v.id("users")) },
  handler: async (ctx, args) => {
    const idToUsername: Record<Id<"users">, string> = {};
    for (const userId of args.userIds) {
      const user = await ctx.db.get("users", userId);
      if (user) {
        idToUsername[user._id] = user.username;
      }
    }

    return idToUsername;
  },
});
```

- Be strict with types, particularly around id's of documents. For example, if a function takes in an id for a document in the 'users' table, take in `Id<'users'>` rather than `string`.
- For typed app environment variables, declare them in `convex/convex.config.ts` with `defineApp({ env: { MY_KEY: v.optional(v.string()) } })` and read them with `env` from `./_generated/server` instead of `process.env`.

## Full text search guidelines

- A query for "10 messages in channel '#general' that best match the query 'hello hi' in their body" would look like:

const messages = await ctx.db
.query("messages")
.withSearchIndex("search_body", (q) =>
q.search("body", "hello hi").eq("channel", "#general"),
)
.take(10);

## Vector search guidelines

- Store embeddings in a field validated with `v.array(v.float64())` and declare a vector index on it in the schema:

```ts
documents: defineTable({
  title: v.string(),
  category: v.string(),
  embedding: v.array(v.float64()),
}).vectorIndex("by_embedding", {
  vectorField: "embedding",
  dimensions: 1536,
  filterFields: ["category"],
}),
```

- `dimensions` must exactly match the length of the vectors you store and search with.
- `ctx.vectorSearch` is ONLY available in actions - not in queries or mutations:

```ts
const results = await ctx.vectorSearch("documents", "by_embedding", {
  vector: args.embedding,
  limit: 10,
  filter: (q) => q.eq("category", args.category),
});
```

- The vector search `filter` supports only equality on declared `filterFields` and `q.or(...)` - there is no AND across different fields and no inequality. Push what you can into the vector filter and apply any remaining predicates after hydration.
- Vector search returns only `{ _id, _score }` pairs ordered by descending similarity score - not full documents. Because actions have no `ctx.db`, hydrate the hits through an internal query, preserve the vector search's order, and pair each score with its document by ID.

## Component guidelines

- Convex components are installable building blocks (e.g. `@convex-dev/aggregate`, `@convex-dev/rate-limiter`) with their own isolated tables and functions. Install the npm package, then mount the component in `convex/convex.config.ts`:

```ts
import { defineApp } from "convex/server";
import aggregate from "@convex-dev/aggregate/convex.config"; // no .js suffix

const app = defineApp();
app.use(aggregate);
export default app;
```

- After mounting, the generated `components` object in `convex/_generated/api` references the component (e.g. `components.aggregate`), and is passed to the component's client class.
- Component functions are not exposed to clients; the app's own queries and mutations wrap them. Perform authentication and authorization in the app functions before calling into a component.
- Component reads and writes participate in the calling mutation's transaction. When a component mirrors state from one of your tables (like an aggregate over a table), update the component in the SAME mutation as every insert, patch, replace, or delete of that table - never from a separate function - so the two can never drift.
- To author a LOCAL component: a directory under `convex/` with its own `convex.config.ts` (`export default defineComponent("myName");` - the argument is the name string), its own `schema.ts`, and functions built from that directory's own `_generated/server`. Mount it from the root config (`app.use(myName)` - no options), and reference its functions through the generated `components` object INCLUDING the module segment: a function in `convex/myName/index.ts` is `components.myName.index.myFunction`, never `components.myName.myFunction`.
- For per-key quotas, cooldowns, or throttling (N operations per period, retry-after), use the `@convex-dev/rate-limiter` component - hand-rolled counter or window-scan implementations admit races under concurrency and lose quota when a mutation fails.
- For chat or assistant features where an LLM replies inside a durable conversation - per-user resumable histories, recorded tool-call steps, several assistants sharing one conversation - use the `@convex-dev/agent` component: mount it, create one component thread per conversation, and generate/read through it (`createThread(ctx, components.agent, ...)`, `new Agent(components.agent, { name, languageModel, tools }).generateText(ctx, { threadId }, { prompt })`, `listMessages`). Do not hand-roll a messages table or call an LLM SDK directly from your functions for these.
- For async Convex functions needing bounded parallelism, serialized mutation work, or completion callbacks, use `@convex-dev/workpool`; retry only idempotent actions.
- For ephemeral presence - who is online/viewing/typing in a room, tracked by client heartbeats with session tokens, multi-session aggregation (one entry per user across tabs), and timeout-to-offline - use the `@convex-dev/presence` component - hand-rolled lastSeen tables need wall-clock query filters that go stale, and per-session rows break the one-entry-per-user contract.
- Calling a component mutation is a subtransaction: if it throws and the caller catches the error, the component's writes roll back while the calling mutation continues and can still commit its own writes.
- To pass a function across a component boundary, mint a handle in the app: `const handle = await createFunctionHandle(internal.index.myCallback);` (from `convex/server`; async, takes only the function reference - `getFunctionHandle` and `getFunctionName` are not this API). Send it as a string; the receiver casts it back and invokes it: `await ctx.runMutation(args.handle as FunctionHandle<"mutation">, callbackArgs);`.

## Query guidelines

- Prefer `.withIndex()` and express every predicate supported by the index in its index range. A subsequent `.filter()` is acceptable for additional predicates that cannot be expressed by that index. Filtering happens after the index scan and does not reduce rows read, so it does not make an otherwise unbounded query scalable.
- Do not read the wall clock inside a query. Queries are not rerun merely because time advances, so results derived from `Date.now()` or a zero-argument `new Date()` can become stale, and wall-clock reads also reduce query-cache reuse. Instead, pass the current time in as an argument and let the client refresh it, or materialize time-based state with scheduled mutations that update a flag field. (`Date.now()` is fine in mutations and actions.)
- If the user does not explicitly tell you to return all results from a query you should ALWAYS return a bounded collection instead. So that is instead of using `.collect()` you should use `.take()` or paginate on database queries. This prevents future performance issues when tables grow in an unbounded way.
- Never use `.collect().length` to count rows. Convex has no built-in count operator. For a simple total, maintain a denormalized counter document updated in your mutations. When queries need aggregates over many rows - counts, sums, ranks/positions, or offset access, whole-table or within a key range - use the `@convex-dev/aggregate` component (O(log n) reads; keep it updated in the same mutation as every source-table write).
- Convex queries do NOT support `.delete()`. To delete all documents matching a query, read them (in `.take(n)` batches or via async iteration) and call `ctx.db.delete("tasks", row._id)` on each.
- Convex mutations are transactions with limits on the documents and bytes they read and write. If a mutation needs to process more documents than fit in a single transaction (e.g. bulk deletion on a large table), process one batch, then `await ctx.scheduler.runAfter(0, internal.myModule.myMutation, args)` to continue in a fresh transaction. A fixed `.take(n)` batch is the default when document sizes are uniform; when they vary, iterate with `for await (const row of query)` and after each write `await ctx.meta.getTransactionMetrics()`, scheduling the continuation and returning as soon as any needed `.remaining` metric (e.g. `metrics.bytesRead.remaining`) falls to a safety reserve.
- Use `.unique()` to get a single document from a query. This method will throw an error if there are multiple documents that match the query.
- When using async iteration, don't use `.collect()` or `.take(n)` on the result of a query. Instead, use the `for await (const row of query)` syntax.

### Ordering

- Queries default to ascending order over the selected index key. A plain table scan uses the built-in `by_creation_time` index, so it returns documents in ascending `_creationTime` order; a query using a custom index defaults to ascending order across that index's entire key.
- You can use `.order('asc')` or `.order('desc')` to pick whether a query is in ascending or descending order. If the order isn't specified, it defaults to ascending.
- Document queries that use indexes will be ordered based on the columns in the index and can avoid slow table scans.
- Convex appends `_creationTime` as the final column of every database index. An index on `["points"]` therefore orders by `points`, then `_creationTime`. `.order("desc")` reverses the entire index key, so rows with equal `points` come back newest first. Rely on this built-in tiebreak instead of re-sorting results in JavaScript.

## Mutation guidelines

- Use `ctx.db.replace` to fully replace an existing document. This method will throw an error if the document does not exist. Syntax: `await ctx.db.replace("tasks", taskId, { name: "Buy milk", completed: false })`
- Use `ctx.db.patch` to shallow merge updates into an existing document. This method will throw an error if the document does not exist. Syntax: `await ctx.db.patch("tasks", taskId, { completed: true })`

## Action guidelines

- Always add `"use node";` to the top of files containing actions that use Node.js built-in modules.
- Never add `"use node";` to a file that also exports queries or mutations. Only actions can run in the Node.js runtime; queries and mutations must stay in the default Convex runtime. If you need Node.js built-ins alongside queries or mutations, put the action in a separate file.
- `fetch()` is available in the default Convex runtime. You do NOT need `"use node";` just to use `fetch()`.
- Never use `ctx.db` inside of an action. Actions don't have access to the database.
- Below is an example of the syntax for an action:

```ts
import { action } from "./_generated/server";

export const exampleAction = action({
  args: {},
  handler: async (ctx, args) => {
    console.log("This action does not return anything");
    return null;
  },
});
```

## Scheduling guidelines

### Cron guidelines

- Only use the `crons.interval` or `crons.cron` methods to schedule cron jobs. Do NOT use the `crons.hourly`, `crons.daily`, or `crons.weekly` helpers.
- Both cron methods take in a FunctionReference. Do NOT try to pass the function directly into one of these methods.
- Define crons by declaring the top-level `crons` object, calling some methods on it, and then exporting it as default. For example,

```ts
import { cronJobs } from "convex/server";
import { internal } from "./_generated/api";
import { internalAction } from "./_generated/server";

const empty = internalAction({
  args: {},
  handler: async (ctx, args) => {
    console.log("empty");
  },
});

const crons = cronJobs();

// Run `internal.crons.empty` every two hours.
crons.interval("delete inactive users", { hours: 2 }, internal.crons.empty, {});

export default crons;
```

- You can register Convex functions within `crons.ts` just like any other file.
- If a cron calls an internal function, always import the `internal` object from '\_generated/api', even if the internal function is registered in the same file.

## Testing guidelines

- Use `convex-test` with `vitest` and `@edge-runtime/vm` to test Convex functions. Always install the latest versions of these packages. Configure vitest with `environment: "edge-runtime"` in `vitest.config.ts`.

Test files go inside the `convex/` directory. You must pass a module map from `import.meta.glob` to `convexTest`:

```typescript
/// <reference types="vite/client" />
import { convexTest } from "convex-test";
import { expect, test } from "vitest";
import { api } from "./_generated/api";
import schema from "./schema";

const modules = import.meta.glob("./**/*.ts");

test("some behavior", async () => {
  const t = convexTest(schema, modules);
  await t.mutation(api.messages.send, { body: "Hi!", author: "Sarah" });
  const messages = await t.query(api.messages.list);
  expect(messages).toMatchObject([{ body: "Hi!", author: "Sarah" }]);
});
```

The `modules` argument is required so convex-test can discover and load function files. The `/// <reference types="vite/client" />` directive is needed for TypeScript to recognize `import.meta.glob`.

- Only add the `/// <reference types="vite/client" />` directive at the top of test files that call `import.meta.glob`; do NOT add it to non-test files.
- Do NOT add a `compilerOptions.types` allowlist to `tsconfig.json` for type packages you have not installed (e.g. `"node"` without `@types/node`, or `"vite/client"` without vite). Any unresolved entry in `types` fails typechecking with TS2688. Leave `types` unset unless a package genuinely requires it and is installed.

## File storage guidelines

- The `ctx.storage.getUrl()` method returns a signed URL for a given file. It returns `null` if the file doesn't exist.
- Do NOT use the deprecated `ctx.storage.getMetadata` call for loading a file's metadata.

Instead, query the `_storage` system table. For example, you can use `ctx.db.system.get` to get an `Id<"_storage">`.

```
import { query } from "./_generated/server";
import { Id } from "./_generated/dataModel";

type FileMetadata = {
    _id: Id<"_storage">;
    _creationTime: number;
    contentType?: string;
    sha256: string;
    size: number;
}

export const exampleQuery = query({
    args: { fileId: v.id("_storage") },
    handler: async (ctx, args) => {
        const metadata: FileMetadata | null = await ctx.db.system.get("_storage", args.fileId);
        console.log(metadata);
        return null;
    },
});
```

- Convex storage stores items as `Blob` objects. You must convert all items to/from a `Blob` when using Convex storage.

import type { ExtractionAnswer, ExtractionField, ExtractionRequest } from "@notorganic/contracts";

/** Clairic response contract v1. Mirrored in Twyne and the Not Organic gateway.
 * Both copies run extraction-contract-v1.json; no cross-checkout imports.
 * Provider reference: https://developers.cloudflare.com/workers-ai/models/clairic/
 */
const record = (value: unknown): value is Record<string, unknown> =>
  value !== null && typeof value === "object" && !Array.isArray(value);
const finite = (value: unknown): value is number => typeof value === "number" && Number.isFinite(value);
const probability = (value: unknown) => finite(value) && value >= 0 && value <= 1;
const invalid = (): never => { throw new Error("Invalid extraction answer"); };

function date(value: unknown): value is string {
  if (typeof value !== "string" || !/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;
  const parsed = new Date(`${value}T00:00:00Z`);
  return Number.isFinite(parsed.getTime()) && parsed.toISOString().slice(0, 10) === value;
}
function time(value: unknown): value is string {
  return typeof value === "string" && /^(?:[01]\d|2[0-3]):[0-5]\d(?::[0-5]\d(?:\.\d+)?)?(?:Z|[+-](?:[01]\d|2[0-3]):[0-5]\d)?$/.test(value);
}
function scalar(value: unknown, type: string, field: ExtractionField): boolean {
  if (type === "text") return typeof value === "string";
  if (type === "date") return date(value);
  if (type === "time") return time(value);
  if (type === "datetime") return typeof value === "string" && date(value.slice(0, 10)) && value[10] === "T" && time(value.slice(11));
  return finite(value) && (!field.integer || Number.isInteger(value));
}
function validSpan(value: unknown, length: number): value is [number, number] {
  return Array.isArray(value) && value.length === 2 && value.every(n => Number.isSafeInteger(n) && n >= 0) && value[0] <= value[1] && value[1] <= length;
}
function boundary(state: string, offset: number): boolean {
  return !(offset > 0 && offset < state.length && /[\uD800-\uDBFF]/.test(state[offset - 1]!) && /[\uDC00-\uDFFF]/.test(state[offset]!));
}
/** Character offsets are underspecified upstream. Accept either convention only
 * when it reconstructs the exact supplied text, then expose UTF-16 everywhere.
 * Never search for a matching occurrence: that would discard source provenance.
 */
function textSpan(source: string | undefined, raw: unknown, value: unknown): [number, number] {
  if (source === undefined || typeof value !== "string" || !validSpan(raw, source.length)) return invalid();
  const [start, end] = raw;
  if (boundary(source, start) && boundary(source, end) && source.slice(start, end) === value) return [start, end];
  const characters = Array.from(source);
  if (end <= characters.length && characters.slice(start, end).join("") === value) {
    return [characters.slice(0, start).join("").length, characters.slice(0, end).join("").length];
  }
  return invalid();
}
function probabilities(answer: Record<string, unknown>): void {
  for (const key of ["p_null", "confidence", "p_below", "p_above"]) {
    if (answer[key] !== undefined && !probability(answer[key])) invalid();
  }
  if (answer.unit !== undefined && typeof answer.unit !== "string") invalid();
}
function distribution(answer: Record<string, unknown>, field: ExtractionField): void {
  probabilities(answer);
  const numeric = finite(field.min) && finite(field.max);
  const dated = date(field.min) && date(field.max);
  if ((!numeric && !dated) || field.min! >= field.max!) invalid();
  const inRange = (value: unknown): value is number | string =>
    (numeric ? finite(value) : date(value)) && (value as number) >= (field.min as number) && (value as number) <= (field.max as number);
  if (![answer.p10, answer.median, answer.p90].every(inRange) || (answer.p10 as number) > (answer.median as number) || (answer.median as number) > (answer.p90 as number)) invalid();
  for (const key of ["value", "mean"]) if (answer[key] !== undefined && !inRange(answer[key])) invalid();
  if (answer.value !== undefined && answer.value !== answer.median) invalid();
  if (answer.quantiles !== undefined) {
    if (!Array.isArray(answer.quantiles) || answer.quantiles.length !== 99 || !answer.quantiles.every(inRange) || answer.quantiles.some((value, i, all) => i > 0 && value < all[i - 1])) invalid();
  }
}

/** Reject an entire response if any requested answer breaks the typed contract. */
export function validateExtractionAnswers(
  request: Pick<ExtractionRequest, "state" | "fields"> & { images?: string[] },
  raw: unknown,
  stateText?: string,
): Record<string, ExtractionAnswer> {
  const names = Object.keys(request.fields);
  if (!record(raw) || Object.keys(raw).length !== names.length || names.some(name => !Object.hasOwn(raw, name))) invalid();
  const source = request.images?.length ? stateText : request.state;
  return Object.fromEntries(names.map(name => {
    const answer = raw[name], field = request.fields[name]!;
    if (!record(answer) || answer.type !== field.type || !Object.hasOwn(answer, "value")) return invalid();
    const normalized = { ...answer };
    probabilities(answer);
    if (field.type === "estimate") {
      if (answer.value === undefined) invalid();
      distribution(answer, field);
    } else if (field.type === "forecast") {
      if (!Number.isInteger(field.horizon) || field.horizon! < 1 || field.horizon! > 64 || !Array.isArray(answer.value) || answer.value.length !== field.horizon) invalid();
      let steps: unknown[];
      if (answer.steps !== undefined) {
        if (!Array.isArray(answer.steps) || answer.steps.length !== field.horizon) invalid();
        steps = answer.steps;
      } else {
        if (![answer.median, answer.p10, answer.p90].every(v => Array.isArray(v) && v.length === field.horizon)) invalid();
        steps = (answer.median as unknown[]).map((median, i) => ({ median, p10: (answer.p10 as unknown[])[i], p90: (answer.p90 as unknown[])[i] }));
      }
      steps.forEach((step, i) => {
        if (!record(step)) invalid();
        distribution(step, field);
        if ((answer.value as unknown[])[i] !== step.median) invalid();
      });
      // Validate alternate parallel arrays too when a provider supplies both forms.
      for (const key of ["median", "p10", "p90", "mean"] as const) {
        const values = answer[key];
        if (values !== undefined && (!Array.isArray(values) || values.length !== field.horizon || values.some((v, i) => v !== (steps[i] as Record<string, unknown>)[key]))) invalid();
      }
    } else if (field.type === "list") {
      if (!Array.isArray(answer.value) || !["text", "number", "date"].includes(field.items ?? "") || !answer.value.every(value => scalar(value, field.items!, field))) invalid();
      if (field.items === "text" || answer.spans !== undefined) {
        if (!Array.isArray(answer.spans) || answer.spans.length !== answer.value.length) invalid();
        const spans = answer.spans.map((span, i) => field.items === "text"
          ? textSpan(source, span, (answer.value as unknown[])[i])
          : validSpan(span, source?.length ?? -1) ? span : invalid());
        if (spans.some((span, i) => i > 0 && span[0] < spans[i - 1]![1])) invalid();
        normalized.spans = spans;
      }
    } else {
      if (answer.value !== null && !scalar(answer.value, field.type, field)) invalid();
      if (answer.guess !== undefined && answer.guess !== null && !scalar(answer.guess, field.type, field)) invalid();
      if (answer.p_null !== undefined && ((answer.p_null as number) > (field.null_threshold ?? 0.5)) !== (answer.value === null)) invalid();
      if (answer.value !== null && answer.guess !== undefined && answer.guess !== answer.value) invalid();
      if (field.type === "text") {
        const candidate = answer.value ?? answer.guess;
        if (candidate != null) normalized.span = textSpan(source, answer.span, candidate);
        else if (answer.span !== undefined && answer.span !== null) invalid();
      }
    }
    return [name, normalized as unknown as ExtractionAnswer];
  }));
}
import { EXTRACTION_DURATION_UNITS, EXTRACTION_FIELD_TYPES, EXTRACTION_FORECAST_INTERVALS, type ExtractionField, type ExtractionRequest, type ExtractionResult, type ExtractionUsage } from '@notorganic/contracts';
import { judgementCost, validJudgementPrice, type JudgementPrice } from '@notorganic/core';
import { GatewayError } from './errors';
import type { GatewayConfig, VerifiedPrincipal } from './types';
import { record } from './decision-backends/wire';
import { boundedJson } from './representation-meter';
import { prepareRepresentationImage } from './representation-images';
import { validateExtractionAnswers } from './extraction-validation';
export { validateExtractionAnswers } from './extraction-validation';

export const EXTRACTION_ALIAS = 'extraction';
export const EXTRACTION_MAX_BODY_BYTES = 28_000_000;
// Published Workers AI rate: $0.10/M input tokens. Output is never billed.
export const DEFAULT_CLAIRIC_INPUT_TOKEN_MICROUSD = 0.1;
const CLAIRIC_MODEL = '@cf/cloudflare/clairic';
const MAX_FIELDS = 64;
const MAX_STATE_CHARS = 96_000;
const MAX_FIELD_CHARS = 32_000;
// Clairic splits fields that do not fit beside the state into parallel 8,192-token passes,
// and every pass re-reads the whole state, so input tokens grow with the pass count.
const PASS_TOKENS = 8_192;
const IMAGE_TOKENS = 8_192;
const MAX_IMAGE_BYTES = 4 * 1024 * 1024;
const MAX_IMAGES_BYTES = 8 * 1024 * 1024;

export interface ExtractionConfig { apiKey: string; accountId?: string; /** Full endpoint override, e.g. an AI Gateway URL. */ url?: string; price: JudgementPrice }

export function extractionConfigFromEnv(env: Record<string, string | undefined>): ExtractionConfig | undefined {
  const apiKey = env.CLOUDFLARE_AI_API_TOKEN?.trim();
  if (!apiKey) return undefined;
  const accountId = env.CLOUDFLARE_ACCOUNT_ID?.trim() || undefined;
  const url = env.CLAIRIC_URL?.trim() || undefined;
  if (!accountId && !url) throw new Error('CLOUDFLARE_AI_API_TOKEN requires CLOUDFLARE_ACCOUNT_ID or CLAIRIC_URL');
  if (url && !url.startsWith('https://')) throw new Error('CLAIRIC_URL must be https');
  const raw = env.EXTRACTION_CLAIRIC_PRICE_PER_INPUT_TOKEN_MICROUSD?.trim();
  const price: JudgementPrice = { unit: 'input_token', microusd: raw ? Number(raw) : DEFAULT_CLAIRIC_INPUT_TOKEN_MICROUSD };
  if (!validJudgementPrice(price)) throw new Error('Invalid EXTRACTION_CLAIRIC_PRICE_PER_INPUT_TOKEN_MICROUSD');
  return { apiKey, accountId, url, price };
}

function invalid(message: string, code = 'invalid_extraction_request', param?: string): never {
  throw new GatewayError(400, 'invalid_request_error', message, code, param);
}

const FIELD_NAME = /^[A-Za-z_][A-Za-z0-9_.\-]{0,63}$/;
const FIELD_KEYS = new Set(['type', 'instructions', 'unit', 'integer', 'decimals', 'items', 'min', 'max', 'step', 'scale', 'null_threshold', 'horizon', 'interval']);
const ISO_DATE = /^\d{4}-\d{2}-\d{2}$/;
const bound = (value: unknown) => (typeof value === 'number' && Number.isFinite(value)) || (typeof value === 'string' && ISO_DATE.test(value));

function validField(name: string, raw: unknown): ExtractionField {
  if (!FIELD_NAME.test(name)) invalid('Field names must match ^[A-Za-z_][A-Za-z0-9_.-]{0,63}$.', 'invalid_field_name', name);
  if (!record(raw) || Object.keys(raw).some(key => !FIELD_KEYS.has(key))) invalid('Each field is an object with known keys.', 'invalid_field', name);
  const f = raw as Record<string, unknown>;
  const type = f.type as ExtractionField['type'];
  if (!EXTRACTION_FIELD_TYPES.includes(type)) invalid(`Field type must be one of ${EXTRACTION_FIELD_TYPES.join(', ')}.`, 'invalid_field_type', name);
  if (f.instructions !== undefined && typeof f.instructions !== 'string') invalid('instructions must be a string.', 'invalid_field', name);
  if (f.unit !== undefined && (typeof f.unit !== 'string' || (type === 'duration' && !(EXTRACTION_DURATION_UNITS as readonly string[]).includes(f.unit)))) invalid('Use a string unit; durations take seconds through years.', 'invalid_field', name);
  if (f.integer !== undefined && (typeof f.integer !== 'boolean' || !['number', 'duration'].includes(type))) invalid('integer applies to numbers and durations.', 'invalid_field', name);
  if (f.decimals !== undefined && (!Number.isInteger(f.decimals) || (f.decimals as number) < 0 || (f.decimals as number) > 6)) invalid('decimals must be an integer from 0 to 6.', 'invalid_field', name);
  if (type === 'list' ? !['text', 'number', 'date'].includes(f.items as string) : f.items !== undefined) invalid('List fields require items: text, number or date.', 'invalid_field', name);
  const ranged = type === 'estimate' || type === 'forecast';
  if (ranged ? !bound(f.min) || !bound(f.max) : f.min !== undefined || f.max !== undefined) invalid('Estimates and forecasts require numeric or ISO date min and max.', 'invalid_field', name);
  if (ranged && typeof f.min === typeof f.max && (f.min as number | string) >= (f.max as number | string)) invalid('min must be below max.', 'invalid_field', name);
  if (f.step !== undefined && (type !== 'estimate' || !((typeof f.step === 'number' && f.step > 0 && Number.isFinite(f.step)) || f.step === 'month' || f.step === 'year'))) invalid('step applies to estimates: a positive number, month or year.', 'invalid_field', name);
  if (f.scale !== undefined && !['linear', 'log'].includes(f.scale as string)) invalid('scale is linear or log.', 'invalid_field', name);
  if (f.scale === 'log' && ((typeof f.min === 'number' && f.min <= 0) || typeof f.min === 'string')) invalid('Log scale needs a positive numeric min.', 'invalid_field', name);
  if (f.null_threshold !== undefined && (typeof f.null_threshold !== 'number' || !(f.null_threshold > 0 && f.null_threshold <= 1))) invalid('null_threshold must be in (0, 1].', 'invalid_field', name);
  if (type === 'forecast' ? !Number.isInteger(f.horizon) || (f.horizon as number) < 1 || (f.horizon as number) > 64 : f.horizon !== undefined) invalid('Forecasts require an integer horizon from 1 to 64.', 'invalid_field', name);
  if (type === 'forecast' ? !(EXTRACTION_FORECAST_INTERVALS as readonly string[]).includes(f.interval as string) : f.interval !== undefined) invalid(`Forecasts require interval: ${EXTRACTION_FORECAST_INTERVALS.join(', ')}.`, 'invalid_field', name);
  return f as unknown as ExtractionField;
}

export function validateExtractionRequest(body: unknown): ExtractionRequest {
  if (!record(body)) invalid('An extraction request body is required.', 'invalid_body');
  const { model, state, fields, images, reference_date, options, ...rest } = body;
  if (Object.keys(rest).length) invalid(`Unknown field: ${Object.keys(rest)[0]}.`, 'invalid_body');
  if (model !== undefined && model !== 'extraction' && model !== 'extraction-clairic') invalid('Use an extraction model alias.', 'invalid_model');
  if (state !== undefined && typeof state !== 'string') invalid('state must be a string.', 'invalid_state');
  if (images !== undefined && (!Array.isArray(images) || images.length > 4 || images.some(image => typeof image !== 'string'))) invalid('Use at most four HTTPS or data URL images.', 'invalid_images');
  if (!(state as string | undefined)?.length && !(images as string[] | undefined)?.length) invalid('Send non-empty state or at least one image.', 'invalid_state');
  if (((state as string | undefined)?.length ?? 0) > MAX_STATE_CHARS) invalid('The state is too large.', 'state_too_large');
  if (!record(fields) || !Object.keys(fields).length) invalid('Send at least one field.', 'invalid_fields');
  if (Object.keys(fields).length > MAX_FIELDS) invalid(`Send at most ${MAX_FIELDS} fields.`, 'too_many_fields');
  const normalized = Object.fromEntries(Object.entries(fields).map(([name, field]) => [name, validField(name, field)]));
  if (JSON.stringify(normalized).length > MAX_FIELD_CHARS) invalid('The field specs are too large.', 'fields_too_large');
  if (reference_date !== undefined && (typeof reference_date !== 'string' || !ISO_DATE.test(reference_date))) invalid('reference_date must be an ISO date.', 'invalid_reference_date');
  if (options !== undefined && (!record(options) || Object.entries(options).some(([key, value]) => !['include_quantiles', 'return_state_text'].includes(key) || typeof value !== 'boolean'))) invalid('options accepts boolean include_quantiles and return_state_text.', 'invalid_options');
  return {
    ...(model !== undefined ? { model: model as ExtractionRequest['model'] } : {}),
    ...(state !== undefined ? { state: state as string } : {}),
    fields: normalized,
    ...(images !== undefined ? { images: images as string[] } : {}),
    ...(reference_date !== undefined ? { reference_date: reference_date as string } : {}),
    ...(options !== undefined ? { options: options as ExtractionRequest['options'] } : {}),
  };
}

/** Reservation ceiling: every pass re-reads state and images, doubled for tokenizer headroom. */
export function extractionMaxInputTokens(request: ExtractionRequest): number {
  const stateTokens = Math.ceil((request.state?.length ?? 0) / 4) + (request.images?.length ?? 0) * IMAGE_TOKENS;
  const schemaTokens = Math.ceil(JSON.stringify(request.fields).length / 4) + Object.keys(request.fields).length * 16;
  const room = Math.max(1_024, PASS_TOKENS - Math.min(stateTokens, PASS_TOKENS - 1_024));
  const passes = Math.min(Object.keys(request.fields).length, Math.max(1, Math.ceil(schemaTokens / room)));
  return (passes * (stateTokens + 256) + schemaTokens) * 2;
}

function normalizedUsage(value: unknown): ExtractionUsage | null {
  if (!record(value)) return null;
  const count = (n: unknown) => typeof n === 'number' && Number.isSafeInteger(n) && n >= 0;
  if (!count(value.input_tokens) || !count(value.output_tokens)) return null;
  const usage: ExtractionUsage = { input_tokens: value.input_tokens as number, output_tokens: value.output_tokens as number };
  for (const key of ['state_tokens', 'image_tokens', 'schema_tokens', 'passes'] as const) if (count(value[key])) usage[key] = value[key] as number;
  return usage;
}

/** Upstream error text can echo the caller's own document. Never forward it. */
function upstreamFailure(status: number): GatewayError {
  if (status === 429) return new GatewayError(429, 'rate_limit_error', 'Extraction is rate limited upstream.', 'extraction_rate_limited');
  if (status === 401 || status === 403) return new GatewayError(503, 'api_error', 'Extraction is not configured correctly.', 'extraction_invalid_configuration');
  if (status === 400 || status === 413 || status === 422) return new GatewayError(400, 'invalid_request_error', 'The extraction request was rejected as malformed.', 'extraction_malformed');
  if (status === 503 || status === 529) return new GatewayError(503, 'api_error', 'Extraction is temporarily overloaded.', 'extraction_overloaded');
  return new GatewayError(502, 'api_error', 'The extraction provider could not answer.', 'extraction_upstream_error');
}

function imageBytes(dataUrl: string): number {
  const base64 = dataUrl.slice(dataUrl.indexOf(',') + 1);
  return Math.floor(base64.length * 3 / 4) - (base64.endsWith('==') ? 2 : base64.endsWith('=') ? 1 : 0);
}

export class ExtractionGateway {
  constructor(private readonly config: GatewayConfig) {}

  models(): string[] { return this.config.extraction ? ['extraction', 'extraction-clairic'] : []; }

  /** Reserve against the account, call Clairic, settle on reported input tokens; same discipline as JudgementGateway. */
  async extract(principal: VerifiedPrincipal, body: unknown, idempotencyKey: string, requestHash: string): Promise<ExtractionResult> {
    const request = validateExtractionRequest(body);
    const configured = this.config.extraction;
    if (!configured) throw new GatewayError(503, 'api_error', 'This extraction model is not configured with credentials and a price.', 'model_unavailable');
    const loaders = await Promise.all((request.images ?? []).map(prepareRepresentationImage));
    const maxCostMicrousd = Math.max(50, judgementCost(configured.price, extractionMaxInputTokens(request)));
    if (maxCostMicrousd > Math.min(principal.maxCostMicrousd, this.config.maxAllowedCostMicrousd ?? Number.MAX_SAFE_INTEGER)) {
      throw new GatewayError(402, 'insufficient_quota', 'The extraction exceeds the request budget.', 'budget_exceeded');
    }
    const alias = request.model ?? EXTRACTION_ALIAS;
    const reservation = await this.config.store.reserve({
      requestId: crypto.randomUUID(), idempotencyKey,
      orgContext: principal.orgContext, agentContext: principal.agentContext, sessionVersion: principal.sessionVersion,
      accountId: principal.accountId, product: principal.product, feature: 'extraction', alias,
      maxCostMicrousd, pricingVersion: this.config.pricingVersion ?? 'v1', requestHash,
    });
    if (reservation.status === 'settled' && reservation.response) {
      const { model, answers, truncated, state_text, usage } = reservation.response;
      return { model, answers, truncated, ...(state_text !== undefined ? { state_text } : {}), usage } as ExtractionResult;
    }
    if (reservation.status !== 'reserved') throw new GatewayError(409, 'conflict_error', 'This extraction request has already been submitted.', 'idempotency_conflict');
    const requestId = reservation.requestId;

    try {
      if (loaders.length) {
        request.images = await Promise.all(loaders.map(load => load()));
        const sizes = request.images.map(imageBytes);
        if (sizes.some(size => size > MAX_IMAGE_BYTES) || sizes.reduce((a, b) => a + b, 0) > MAX_IMAGES_BYTES) {
          throw new GatewayError(413, 'invalid_request_error', 'Extraction images are limited to 4 MiB each and 8 MiB together.', 'input_too_large');
        }
      }
      await this.config.store.markDispatched({ requestId });
    } catch (error) {
      await this.config.store.release({ requestId, reason: 'dispatch_not_started' });
      throw error;
    }

    let response: Response;
    try {
      response = await this.#fetch(configured, request.images?.length ? { ...request, options: { ...request.options, return_state_text: true } } : request);
    } catch {
      await this.config.store.reconcile({ requestId, conservativeCostMicrousd: maxCostMicrousd, reason: 'extraction_delivery_unknown' });
      throw new GatewayError(502, 'api_error', 'The extraction provider could not be reached.', 'extraction_unreachable');
    }
    if (!response.ok) {
      await this.config.store.release({ requestId, reason: `upstream_${response.status}` });
      throw upstreamFailure(response.status);
    }

    await this.config.store.markAccepted({ requestId });
    let result: Omit<ExtractionResult, 'usage'>;
    let usage: ExtractionUsage | null;
    try {
      const envelope = await boundedJson(response, 4_000_000);
      // The REST API wraps model output in { result, success }; AI Gateway and bindings may not.
      const payload: Record<string, unknown> = record(envelope.result) ? envelope.result : envelope;
      if (typeof payload.model !== 'string' || !/^(?:clairic|@cf\/cloudflare\/clairic)(?:[-@:.][\w.-]+)?$/.test(payload.model)) throw new Error('Unexpected model');
      if (typeof payload.truncated !== 'boolean') throw new Error('Missing truncated');
      result = {
        model: `extraction-clairic/${payload.model.replace(/^@cf\/cloudflare\//, '')}`,
        answers: validateExtractionAnswers(request, payload.answers, typeof payload.state_text === 'string' ? payload.state_text : undefined),
        truncated: payload.truncated,
        ...(request.options?.return_state_text && typeof payload.state_text === 'string' ? { state_text: payload.state_text } : {}),
      };
      usage = normalizedUsage(payload.usage);
    } catch {
      await this.config.store.reconcile({ requestId, conservativeCostMicrousd: maxCostMicrousd, reason: 'invalid_upstream_response' });
      throw new GatewayError(502, 'api_error', 'The extraction provider returned invalid answers or model identity.', 'extraction_invalid_response');
    }

    let cost: number | null = null;
    try { cost = usage ? judgementCost(configured.price, usage.input_tokens) : null; } catch { /* Overflowing usage reconciles at the ceiling. */ }
    if (cost === null) {
      await this.config.store.reconcile({ requestId, conservativeCostMicrousd: maxCostMicrousd, reason: 'extraction_usage_unavailable' });
    } else {
      const charged = Math.min(cost, maxCostMicrousd);
      await this.config.store.settleWithResponse({
        accountId: principal.accountId, orgContext: principal.orgContext,
        response: { id: requestId, object: 'extraction', ...result, usage },
        requestId, actualCostMicrousd: charged, providerAbsorbedMicrousd: Math.max(0, cost - charged),
        usage: usage ? { input_tokens: usage.input_tokens, output_tokens: usage.output_tokens } : undefined,
      });
    }
    await this.#emitSettled(principal, {
      product: principal.product, alias, model: result.model,
      fields: Object.keys(request.fields).length, images: request.images?.length ?? 0, truncated: result.truncated,
      input_tokens: usage?.input_tokens ?? null, passes: usage?.passes ?? null, usage_complete: usage !== null,
      billed_usd: (cost === null ? maxCostMicrousd : Math.min(cost, maxCostMicrousd)) / 1_000_000,
    });
    return { ...result, usage };
  }

  #fetch(configured: ExtractionConfig, request: ExtractionRequest): Promise<Response> {
    const url = configured.url ?? `https://api.cloudflare.com/client/v4/accounts/${encodeURIComponent(configured.accountId!)}/ai/run/${CLAIRIC_MODEL}`;
    return (this.config.fetch ?? fetch)(url, {
      method: 'POST', redirect: 'error', signal: AbortSignal.timeout(30_000),
      headers: { 'content-type': 'application/json', authorization: `Bearer ${configured.apiKey}` },
      body: JSON.stringify({
        model: 'clairic', state: request.state ?? '', fields: request.fields,
        ...(request.images?.length ? { images: request.images } : {}),
        ...(request.reference_date ? { reference_date: request.reference_date } : {}),
        ...(request.options ? { options: request.options } : {}),
      }),
    });
  }

  /** Same HMAC pseudonym as JudgementGateway, so extraction spend joins the per-account series. */
  async #emitSettled(principal: VerifiedPrincipal, properties: Record<string, unknown>): Promise<void> {
    const telemetry = this.config.telemetry;
    if (!telemetry) return;
    try {
      const key = await crypto.subtle.importKey('raw', new Uint8Array(this.config.pseudonymSecret).buffer as ArrayBuffer, { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
      const digest = new Uint8Array(await crypto.subtle.sign('HMAC', key, new TextEncoder().encode(principal.accountId)));
      await telemetry.capture('extraction.settled', Buffer.from(digest).toString('base64url'), properties);
    } catch {
      // Telemetry must never fail an extraction the caller already paid for.
    }
  }
}

